{
  "story": "K-means partitions data into k groups by iteratively assigning points to the nearest centroid and updating centroid positions until convergence.",
  "aha": {
    "stateId": "step-3",
    "observation": "Centroids shift toward the center of their assigned points in each iteration until stability."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "ghost",
      "kind": "previous-state-ghost",
      "bind": {
        "regions": "previous.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Algorithm Step",
      "options": [
        "Init",
        "Assign",
        "Update",
        "Converge"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "K-Means 2D",
        "regions": [
          {
            "id": "c1",
            "label": "Centroid A",
            "kind": "centroid",
            "values": ["x:2, y:2"]
          },
          {
            "id": "c2",
            "label": "Centroid B",
            "kind": "centroid",
            "values": ["x:8, y:8"]
          },
          {
            "id": "points",
            "label": "Data Points",
            "kind": "cluster",
            "values": ["10 points"]
          }
        ],
        "states": [
          {
            "id": "step-0",
            "label": "Initialization",
            "short": "Init",
            "sentence": "Place initial centroids randomly in the feature space.",
            "why": "Starting positions set the baseline for distance calculations.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r1",
                "label": "Iteration",
                "value": "0"
              }
            ]
          },
          {
            "id": "step-1",
            "label": "Assignment",
            "short": "Assign",
            "sentence": "Assign each data point to its closest centroid.",
            "why": "Voronoi regions form around each centroid based on Euclidean distance.",
            "active": ["points"],
            "calloutRegion": "points",
            "readouts": [
              {
                "id": "r2",
                "label": "Assigned",
                "value": "10/10"
              }
            ]
          },
          {
            "id": "step-2",
            "label": "Update",
            "short": "Update",
            "sentence": "Move centroids to the mean coordinates of their assigned points.",
            "why": "Centroids recalculate to minimize intra-cluster variance.",
            "active": ["c1", "c2"],
            "calloutRegion": "c1",
            "readouts": [
              {
                "id": "r3",
                "label": "Shift",
                "value": "1.2 units"
              }
            ]
          },
          {
            "id": "step-3",
            "label": "Convergence",
            "short": "Converge",
            "sentence": "Repeat assignment and update until centroid positions no longer change.",
            "why": "The algorithm stabilizes when cluster assignments remain identical.",
            "active": ["c1", "c2", "points"],
            "calloutRegion": "c2",
            "readouts": [
              {
                "id": "r4",
                "label": "Status",
                "value": "Converged"
              }
            ]
          }
        ]
      }
    ]
  }
}
